<script setup>
import {onMounted,ref} from 'vue';
import {listRecords} from '../db/dentaVaultDb.js';
const emit=defineEmits(['close']);const loading=ref(true);const records=ref([]);const filter=ref('All');const loadError=ref('');
const categories=[['qlf_odontogram_scans','Biofilm'],['tmj_jva_studies','TMJ'],['stephan_ph_logs','Stephan'],['vita_shade_records','Shade'],['brush_cdt_audits','Brush & quote']];
const load=async()=>{loading.value=true;loadError.value='';try{const found=[];for(const [store,label] of categories){const rows=await listRecords(store);for(const row of rows)found.push({...row,store,label})}records.value=found.sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0))}catch{loadError.value='Records could not be read from this browser storage. You can still use the simulators without saving.'}finally{loading.value=false}};
onMounted(load);
const visible=()=>filter.value==='All'?records.value:records.value.filter(row=>row.label===filter.value);
const summary=row=>{const parts=[];if(row.tooth)parts.push(`Tooth #${row.tooth} · ${row.surface||''}`);if(row.pattern)parts.push(row.pattern);if(row.challenge)parts.push(row.challenge);if(row.match)parts.push(`Match ${row.match}`);if(row.total!=null)parts.push(`Total ${row.total}`);if(row.minPh!=null)parts.push(`Model min pH ${row.minPh}`);if(row.opening!=null)parts.push(`Opening ${row.opening} mm`);return parts.join(' · ')||JSON.stringify(row).slice(0,110)};
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="modal glass"><div class="modal-head"><div><div class="eyebrow">Private · device storage</div><h2>Local record vault</h2><p class="small">Saved examples stay on this device. No remote sync server is configured.</p></div><button class="close" @click="emit('close')">×</button></div><div class="preset-list" style="margin:14px 0"><button v-for="name in ['All','Biofilm','TMJ','Stephan','Shade','Brush & quote']" :key="name" class="preset" :class="{active:filter===name}" @click="filter=name">{{name}}</button></div><div v-if="loading" class="small">Loading local records…</div><div v-else-if="loadError" class="empty-state">{{loadError}}</div><div v-else-if="!visible().length" class="empty-state">No saved records yet. Try a simulator and choose “Save”.</div><div v-else class="record-list"><article v-for="(record,index) in visible().slice(0,40)" :key="`${record.store}-${record.id||index}`" class="record-row"><div class="record-tag">{{record.label}}</div><div class="record-content"><strong>{{summary(record)}}</strong><span>{{record.createdAt?new Date(record.createdAt).toLocaleString():'Local record'}}</span></div></article></div><div v-if="records.length>40" class="footnote">Showing the latest 40 of {{records.length}} records.</div></section></div></template>
<style scoped>.record-list{max-height:52vh;overflow:auto;display:grid;gap:8px}.record-row{display:flex;gap:10px;align-items:flex-start;border:1px solid var(--line);border-radius:12px;padding:11px;background:#ffffff05}.record-tag{font:9px 'DM Mono',monospace;color:#8cebd5;text-transform:uppercase;min-width:76px}.record-content{display:grid;gap:5px;min-width:0}.record-content strong{font-size:10px;font-weight:600;overflow-wrap:anywhere}.record-content span{font-size:9px;color:var(--muted)}.empty-state{padding:34px 18px;text-align:center;border:1px dashed var(--line);border-radius:14px;color:var(--muted);font-size:11px}</style>
